var mySize;
var seed = Math.random() * 1000;
var color1, color2;
let colors1 = "e3d7a3BF-f5989d33-ea618e40-fce4d6b3-caac7180".split("-").map((a) => "#" + a);
let colors2 = "6cbbd4BF-5863b140-5282a1BF-fee8f733-c1f29b80".split("-").map((a) => "#" + a);
let colors3 = "1b1b1bBF-29292940-f3f3f3BF-222222b3-ff000080".split("-").map((a) => "#" + a);
let colors4 = "70c1b3BF-aaf0d340-50514f33-ffe066b3-247ba080".split("-").map((a) => "#" + a);
let colors5 = "3c1642BF-38637540-08637533-b2ff9eb3-1dd3b080".split("-").map((a) => "#" + a);
let colorbg = "2c363f".split("-").map((a) => "#" + a);
let colorbg2 = "2c363f07".split("-").map((a) => "#" + a);

function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
  createCanvas(windowWidth, windowHeight);
  background(colorbg);
  //colorMode(HSB, 360, 100, 100, 100);
  t = rez = c = n = 0.01;
  color1 = random([colors1,colors2,colors3,colors4,colors5]);
	color2 = random([colors1,colors2,colors3,colors4,colors5]);
  // pixelDensity(5);
  xOff = 0;
  yOff = 0;
}

function draw() {
	randomSeed(seed);
  background(colorbg2);

  // stroke(random(random([colors1,colors2,colors3,colors4,colors5])));
	let plus = int(random(15,20));
  for (let i = xOff; i < width - xOff; i += plus) {
    for (let j = yOff; j < height - yOff; j += plus) {
			strokeWeight(random(1));
      strokeCap(SQUARE);
      var n = noise(i * rez, j * rez + t);
      if (n > 0.35) {
				noStroke();
        fill(random(color1));
      } else {
				noFill();
        stroke(random(color2));
      }

			push();
			translate(i, j)
      if (n > 0.5) {
        circle(0,0, plus*1.05);
      } else {
        circle(0,0, plus*0.75);
      }
			pop();
    }
  }
  t += 0.005;
  // noLoop();
}

function keyPressed() {
  //noLoop();
  saveCanvas("20211229-Untitled", "png");
}

